utionSource: \"CMS, State Medicaid and CHIP Eligibility Processing Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3758:    dataPointId: \"cms.medicaid_pi.procedural_disenrollment_share.vt.aug_2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3768:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3774:    resolutionSource: \"CMS, State Medicaid and CHIP Eligibility Processing Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3776:    dataPointId: \"cms.medicaid_pi.procedural_disenrollment_share.wa.aug_2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3786:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3792:    resolutionSource: \"CMS, State Medicaid and CHIP Eligibility Processing Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3794:    dataPointId: \"cms.medicaid_pi.procedural_disenrollment_share.wi.aug_2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3804:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3810:    resolutionSource: \"CMS, State Medicaid and CHIP Eligibility Processing Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3812:    dataPointId: \"cms.medicaid_pi.procedural_disenrollment_share.wv.aug_2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3822:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3828:    resolutionSource: \"CMS, State Medicaid and CHIP Eligibility Processing Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3830:    dataPointId: \"cms.medicaid_pi.procedural_disenrollment_share.wy.aug_2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3840:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3846:    resolutionSource: \"USDA FNS, SNAP Quality Control Payment Error Rates, FY 2025\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3848:    dataPointId: \"fns.snap.share_jurisdictions_at_or_above_6pct.fy2025\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3858:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3864:    resolutionSource: \"USDA FNS, SNAP Quality Control Payment Error Rates, FY 2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3866:    dataPointId: \"fns.snap.total_payment_error_rate.us.fy2026.cost_share_in_effect\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3869:    reasoning: [{ kind: \"heading\", text: \"A policy conditional\" }, { kind: \"text\", text: \"This cell conditions on a policy state, not on data availability: the SNAP cost-share provisions staying law through mid-2027. It isolates the incentive effect the threshold cell can only gesture at — FY 2026 is the first full fiscal year states operate knowing their error rates drive a 5-15 percent benefit match, and FY 2026 rates feed the first match calculations. The conditioning event is machine-checkable against the federal bill tracker, and once the provision is encoded, against the rules corpus.\", }, { kind: \"tool\", tool: \"ledger.lookup\", call: \"ledger.lookup({ source_record_id: \\\"fns.snap.total_payment_error_rate.us.fy2024.official_release\\\" })\", result: \"{ value: 10.93, unit: \\\"percent\\\", observed_at: \\\"2025-06-30\\\" }\" }, { kind: \"tool\", tool: \"fns.lookup\", call: \"fns.lookup({ series: \\\"national_payment_error_rate\\\", years: [\\\"fy2023\\\", \\\"fy2024\\\"] })\", result: \"{ fy2023: 11.68, fy2024: 10.93 }\" }, { kind: \"math\", text: \"Unconditional FY 2025 forecast: 10.2. A binding match incentive historically accelerates corrective action (South Carolina cut 22.6 to 9.3 in one year under far weaker pressure); conditional on the provision surviving, an additional ~0.8pp decline is the modal path.\" }, { kind: \"heading\", text: \"Forecast\" }, { kind: \"text\", text: \"The lower tail is broad corrective-action wins plus favorable QC arbitration; the upper tail is implementation friction and caseload churn offsetting the incentive. If the provision is repealed or delayed, the cell never resolves — that is what makes it a clean reading of the policy's effect.\" }, { kind: \"forecast\", point: 9.4, ciLow: 8.2, ciHigh: 10.7 }],\nsite/src/data/forecast-examples/benefits-delivery.ts:3877:    unit: \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3883:    resolutionSource: \"USDA FNS, SNAP Quality Control Payment Error Rates, FY 2026\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3885:    dataPointId: \"fns.snap.total_payment_error_rate.us.fy2026.cost_share_repealed\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3888:    reasoning: [{ kind: \"heading\", text: \"The counterfactual arm\" }, { kind: \"text\", text: \"This is the mirror of the cost-share-in-effect cell: same outcome, opposite policy state. Exactly one arm resolves. The 0.9-point gap between the two point estimates is the institution's product in miniature — a falsifiable, dated forecast of what a policy choice does to a delivery outcome, published before the choice is made.\" }, { kind: \"tool\", tool: \"ledger.lookup\", call: \"ledger.lookup({ source_record_id: \\\"fns.snap.total_payment_error_rate.us.fy2024.official_release\\\" })\", result: \"{ value: 10.93, unit: \\\"percent\\\", observed_at: \\\"2025-06-30\\\" }\" }, { kind: \"tool\", tool: \"fns.lookup\", call: \"fns.lookup({ series: \\\"national_payment_error_rate\\\", years: [\\\"fy2023\\\", \\\"fy2024\\\"] })\", result: \"{ fy2023: 11.68, fy2024: 10.93 }\" }, { kind: \"math\", text: \"Under repeal, the secular improvement trend (11.68 to 10.93 to ~10.2e) continues but loses the match-driven acceleration; states that already funded corrective action carry some momentum through FY 2026. Wider interval reflects the policy turbulence that any repeal scenario implies.\" }, { kind: \"heading\", text: \"Forecast\" }, { kind: \"text\", text: \"Modal path is roughly flat-to-slightly-better versus FY 2025, without the additional decline the binding incentive would buy. If the provision survives instead, this cell never resolves and its twin does.\" }, { kind: \"forecast\", point: 10.3, ciLow: 9.0, ciHigh: 11.7 }],\nsite/src/data/forecast-examples/benefits-delivery.ts:3896:    \"question\": \"Conditional on the 2025 reconciliation law's Medicaid community-engagement compliance deadline (December 31, 2026) remaining in effect — no enacted statutory delay and no nationwide court stay as of March 31, 2027 — what will the national average Medicaid call-center wait time be in the March 2027 reporting period?\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3897:    \"unit\": \"minutes\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3903:    \"resolutionSource\": \"CMS, State Medicaid and CHIP Applications, Eligibility Determinations, and Enrollment Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3904:    \"resolutionSourceUrl\": \"https://data.medicaid.gov/dataset/6165f45b-ca93-5bb5-9d06-db29c692a360\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3905:    \"resolutionRule\": \"Resolves to the volume-weighted national average Medicaid call-center wait time in minutes for the March 2027 reporting period, computed across all reporting jurisdictions in CMS dataset 6165f45b-ca93-5bb5-9d06-db29c692a360 (each jurisdiction's average wait weighted by its total call volume, latest submission per jurisdiction), when CMS first publishes the period (expected roughly four months later). Conditional on the event 'no federal statute enacted and no nationwide court stay issued on or before 2027-03-31 delays the community-engagement compliance deadline beyond 2027.' If the conditioning event fails, the cell is marked unresolved.\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3934:    \"dataPointId\": \"cms.medicaid_pi.call_center_wait_minutes.us.mar_2027.deadline_holds\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3935:    \"conditionalOn\": \"Medicaid community-engagement compliance deadline (2026-12-31) in effect — no statutory delay or nationwide stay as of 2027-03-31\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3959:        \"text\": \"Minutes on hold is the time tax at its most direct. I rebuild this forecast from the primary CMS series rather than asserting it: the volume-weighted national average Medicaid call-center wait already tripled from 7.3 minutes in May 2025 to a 25.4-minute peak in January 2026 (11.9M calls), settling at 24.0 in February 2026 — the latest period CMS has published. March 2027 is the first full quarter after the December 31, 2026 community-engagement compliance deadline, so the question is how much an implementation pulse adds on top of an already-stressed baseline, net of staffing response.\"\nsite/src/data/forecast-examples/benefits-delivery.ts:3970:        \"call\": \"kff.lookup({ topic: \\\"2025 reconciliation community engagement requirement\\\", fields: [\\\"subject_population\\\", \\\"verification_cadence\\\", \\\"deadline\\\"] })\",\nsite/src/data/forecast-examples/benefits-delivery.ts:3976:        \"call\": \"litigation.lookup({ topic: \\\"community engagement requirement status\\\", as_of: \\\"2026-06\\\" })\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4028:    \"question\": \"Conditional on a federal statute or nationwide court stay, on or before March 31, 2027, delaying the 2025 reconciliation law's Medicaid community-engagement compliance deadline beyond 2027, what will the national average Medicaid call-center wait time be in the March 2027 reporting period?\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4029:    \"unit\": \"minutes\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4035:    \"resolutionSource\": \"CMS, State Medicaid and CHIP Applications, Eligibility Determinations, and Enrollment Data (data.medicaid.gov)\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4036:    \"resolutionSourceUrl\": \"https://data.medicaid.gov/dataset/6165f45b-ca93-5bb5-9d06-db29c692a360\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4037:    \"resolutionRule\": \"Resolves to the volume-weighted national average Medicaid call-center wait time in minutes for the March 2027 reporting period, computed across all reporting jurisdictions in CMS dataset 6165f45b-ca93-5bb5-9d06-db29c692a360 (each jurisdiction's average wait weighted by its total call volume, latest submission per jurisdiction), when CMS first publishes the period (expected roughly four months later). Conditional on the event 'a federal statute enacted or nationwide court stay issued on or before 2027-03-31 delays the community-engagement compliance deadline beyond 2027.' If the conditioning event fails, the cell is marked unresolved. Exactly one cell of this pair resolves; the gap between the arms (33 vs 15 minutes) is the forecasted hold-time cost of the policy state.\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4066:    \"dataPointId\": \"cms.medicaid_pi.call_center_wait_minutes.us.mar_2027.deadline_delayed\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4067:    \"conditionalOn\": \"Medicaid community-engagement compliance deadline delayed beyond 2027 by statute or nationwide stay on or before 2027-03-31\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4091:        \"text\": \"Same outcome, opposite policy state, same model with the work-requirement pulse switched off. If a statute or a nationwide stay delays the community-engagement deadline before April 2027, the implementation wave never lands in Q1; volume reverts toward the renewal-system baseline and staffing catches up. Hold times do not return to the 7-minute world of spring 2025 — renewal volumes and prior churn persist — but the implementation premium does not get added.\"\nsite/src/data/forecast-examples/benefits-delivery.ts:4114:        \"call\": \"litigation.lookup({ topic: \\\"community engagement requirement delay or stay\\\", as_of: \\\"2026-06\\\" })\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4154:    \"question\": \"What is the probability that the 2025 reconciliation law's Medicaid community-engagement compliance deadline (December 31, 2026) is in effect — no enacted statutory delay and no nationwide court stay — as of March 31, 2027?\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4155:    \"unit\": \"percent\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4161:    \"resolutionSource\": \"Federal statute and federal court orders of nationwide effect, via the federal bill tracker and docket records\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4162:    \"resolutionSourceUrl\": \"https://www.kff.org/medicaid/medicaid-work-requirements-tracker-overview/\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4163:    \"resolutionRule\": \"Resolves to 100 if, as of 2027-03-31, no federal statute has been enacted and no court order of nationwide effect is in force that delays the community-engagement compliance deadline of the 2025 reconciliation law beyond calendar 2027; resolves to 0 otherwise. State-specific good-faith extensions granted by the Secretary do not trigger resolution to 0. The event is machine-checkable against the federal bill tracker and, once the provision is encoded, the rules corpus.\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4218:        \"call\": \"litigation.lookup({ topic: \\\"community engagement requirement challenges\\\", as_of: \\\"2026-06\\\" })\",\nsite/src/data/forecast-examples/benefits-delivery.ts:4225:        \"result\": \"CMS published the interim final rule 'Community Engagement Requirement for Certain Individuals' on June 3, 2026: 80 hrs/month, compliance beginning January 1, 2027, binding regulation, projecting 2.3M enrollment reduction 